export function expandToQuestionCount(base: string[], count: number): string[] {
  const suffixes = [
    '',
    ' Provide a step-by-step worked solution.',
    ' Include definitions of all prerequisite terms.',
    ' Show intermediate algebraic or logical steps.',
    ' Explain with a concrete numerical example.',
    ' Compare two standard methods for solving this.',
    ' Identify common misconceptions students make.',
    ' Derive the result from first principles.',
    ' State assumptions and boundary conditions explicitly.',
    ' Relate the answer to a real-world application.',
  ];

  const out: string[] = [];
  for (let i = 0; i < count; i++) {
    const baseQ = base[i % base.length];
    const suffix = suffixes[Math.floor(i / base.length) % suffixes.length];
    const trimmed = baseQ.replace(/[?.!]+$/, '');
    out.push(`${trimmed}${suffix}?`);
  }
  return out;
}
